const fs=require('node:fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
const ids={examples:['lifting','trim','tank','pump','crank','faults'],explorers:['rlc','heat','current','finance'],labs:['stability','controls','engine'],cargo:['cargo'],mollier:['mollier']};
let checks=0;const ok=(v,m)=>{assert.ok(v,m);checks++};
function open(page,id,saved={}){const dom=new JSDOM(fs.readFileSync('students/'+page+'.html','utf8'),{url:'https://example.test/students/'+page+'.html#'+id,runScripts:'outside-only',pretendToBeVisual:true});const w=dom.window;w.matchMedia=()=>({matches:false,addEventListener(){}});w.scrollTo=()=>{};for(const[k,v]of Object.entries(saved))w.localStorage.setItem(k,v);for(const m of fs.readFileSync('students/'+page+'.html','utf8').matchAll(/src="([^"?]+\.js)/g)){w.eval(fs.readFileSync('students/'+m[1],'utf8'));}return dom;}
const storage=w=>Object.fromEntries(Object.keys(w.localStorage).map(k=>[k,w.localStorage.getItem(k)]));
for(const[page,modules]of Object.entries(ids))for(const id of modules){
 let dom=open(page,id),w=dom.window,d=w.document;
 ok(!!w.MT_STUDY_DRAFT,'Draft adapter '+page+'/'+id);
 if(page==='cargo'){d.getElementById('add-operation').click();d.querySelector('#operations tr:last-child [data-key=name]').value='<test draft>';}
 if(page==='mollier'){d.getElementById('pressure-number').value='12';d.getElementById('pressure-number').dispatchEvent(new w.Event('change',{bubbles:true}));}
 else{const input=(page==='labs'?d.getElementById(id):d.querySelector('form')).querySelector('input[type=number]');input.value='';input.dispatchEvent(new w.Event('input',{bubbles:true}));}
 const before=JSON.stringify(w.MT_STUDY_DRAFT.capture());w.MT_STUDY_DRAFT.flush();const data=storage(w);ok(!!data[w.MT_STUDY_DRAFT.key],'Draft saved '+id);dom.window.close();
 dom=open(page,id,data);w=dom.window;d=w.document;ok(JSON.stringify(w.MT_STUDY_DRAFT.capture())===before,'Complete or unfinished draft restored '+page+'/'+id);
 if(page!=='mollier')ok([...d.querySelectorAll('.error,[role=alert]')].some(x=>!x.hidden&&x.textContent),'Invalid draft remains marked '+id);
 if(page==='cargo')ok(d.querySelectorAll('#operations tr').length===3,'Operation count restored');
 const chart=d.querySelector('main svg[viewBox]');const base=chart.getAttribute('viewBox');chart.MT_DIAGRAM_VIEW.zoom(2);ok(chart.getAttribute('viewBox')!==base,'Diagram zoom '+id);const exported=w.MT_STUDY_EXPORT.svgSnapshot(chart);ok(exported.includes('viewBox="'+base+'"'),'Export keeps full diagram '+id);chart.MT_DIAGRAM_VIEW.reset();ok(chart.getAttribute('viewBox')===base,'Diagram reset '+id);
 const enabled=d.querySelector('.study-session input');enabled.checked=false;enabled.dispatchEvent(new w.Event('change'));ok(w.localStorage.getItem('mt.study.autosave.enabled.v1')==='false','Saving can be disabled');
 d.querySelector('.study-session button').click();ok(!Object.keys(w.localStorage).some(k=>k.startsWith('mt.study.draft.v1:')),'Clear removes study drafts');dom.window.close();
}
let dom=open('examples','trim'),w=dom.window;const key=w.MT_STUDY_DRAFT.key;w.document.querySelector('input[name=length]').value='150';w.MT_STUDY_DRAFT.flush();let data=storage(w);const r=JSON.parse(data[key]);r.data[0].key='unexpected-field';data[key]=JSON.stringify(r);dom.window.close();dom=open('examples','trim',data);w=dom.window;ok(w.document.querySelector('input[name=length]').value==='140','Malformed record leaves default data intact');ok(w.document.querySelector('.study-session [role=status]').textContent.includes('could not be restored'),'Malformed storage reported');dom.window.close();
dom=open('examples','trim');w=dom.window;Object.defineProperty(w.Storage.prototype,'setItem',{value(){throw new Error('Quota exceeded')}});w.document.querySelector('input[name=length]').value='150';w.MT_STUDY_DRAFT.flush();ok(w.document.querySelector('.study-session [role=status]').textContent.includes('unavailable or full'),'Failed storage never claims saved');dom.window.close();
dom=open('mollier','mollier');w=dom.window;let mode=w.document.getElementById('process-mode');mode.value='turbine';mode.dispatchEvent(new w.Event('change',{bubbles:true}));w.document.getElementById('process-efficiency').value='0.72';w.MT_STUDY_DRAFT.flush();data=storage(w);dom.window.close();dom=open('mollier','mollier',data);w=dom.window;ok(w.document.getElementById('process-mode').value==='turbine'&&w.document.getElementById('process-efficiency').value==='0.72'&&!w.document.getElementById('process-efficiency-field').hidden,'Unsolved process controls survive reload');dom.window.close();
dom=open('mollier','mollier');w=dom.window;w.document.getElementById('pressure-number').value='';w.document.getElementById('pressure-number').dispatchEvent(new w.Event('input',{bubbles:true}));w.MT_STUDY_DRAFT.flush();data=storage(w);dom.window.close();dom=open('mollier','mollier',data);w=dom.window;ok(w.document.getElementById('pressure-number').value===''&&!w.document.getElementById('input-error').hidden,'Numeric draft typed before blur is preserved and marked');assert.throws(()=>w.MT_MOLLIER_SNAPSHOT());checks++;dom.window.close();
console.log(JSON.stringify({status:'PASS',checks,modules:15,scope:'Raw draft roundtrips, invalid-state marking, operation count, storage failures, clear/disable, zoom/reset and complete SVG exports'}));
